      "default-role-name": "Viewer: Authorized to Read All Books",
      "scope-references": ["$XSAPPNAME.Display"],
      "attribute-references": [ { "name": "Country", "default-values": ["USA", "Germany"] } ]
    },
    {
      "name": "Editor",
      "description": "Edit books",
      "scope-references": ["$XSAPPNAME.Edit"]
    }
  ],
