const { createSecurityContext, XsuaaService, SECURITY_CONTEXT, errors: { ValidationError } } = require("@sap/xssec");

const authService = new XsuaaService(credentials); // xsuaa credentials, for example via @sap/xsenv

app.use(async (req, res, next) => {
  try {
    req[SECURITY_CONTEXT] = await createSecurityContext(authService, { req });
    next();
  } catch (e) {
    res.sendStatus(e instanceof ValidationError ? 401 : 500);
  }
});

app.get("/books", (req, res) => {
  const ctx = req[SECURITY_CONTEXT];
  if (!ctx.checkLocalScope("Display")) {
    return res.sendStatus(403);
  }
  const country = ctx.token.xsUserAttributes?.Country;
  res.send(`Hello ${ctx.token.givenName}, country: ${country}`);
});

